CREATE DATABASE IF NOT EXISTS naser_sgi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE naser_sgi;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS operaciones; DROP TABLE IF EXISTS usuario_sector; DROP TABLE IF EXISTS documentos; DROP TABLE IF EXISTS usuarios; DROP TABLE IF EXISTS zonas; DROP TABLE IF EXISTS sectores;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE sectores(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,slug VARCHAR(80) NOT NULL UNIQUE,orden INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE zonas(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL UNIQUE,activa TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,rol ENUM('admin','supervisor','ventas','operador') NOT NULL,zona_id INT NULL,activo TINYINT(1) NOT NULL DEFAULT 1,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(zona_id) REFERENCES zonas(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE usuario_sector(usuario_id INT NOT NULL,sector_id INT NOT NULL,puede_ver TINYINT(1) NOT NULL DEFAULT 1,puede_editar TINYINT(1) NOT NULL DEFAULT 0,PRIMARY KEY(usuario_id,sector_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(sector_id) REFERENCES sectores(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE documentos(id INT AUTO_INCREMENT PRIMARY KEY,sector_id INT NOT NULL,titulo VARCHAR(180) NOT NULL,descripcion TEXT NULL,tipo ENUM('documentacion','procedimiento') NOT NULL,archivo VARCHAR(255) NULL,activo TINYINT(1) NOT NULL DEFAULT 1,fecha_actualizacion DATE NOT NULL,creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(sector_id) REFERENCES sectores(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE operaciones(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(160) NOT NULL,descripcion TEXT NULL,zona_id INT NULL,estado ENUM('activa','inactiva') NOT NULL DEFAULT 'activa',orden INT NOT NULL DEFAULT 0,FOREIGN KEY(zona_id) REFERENCES zonas(id) ON DELETE SET NULL) ENGINE=InnoDB;

