INSERT INTO usuario_sector SELECT u.id,s.id,1,1 FROM usuarios u CROSS JOIN sectores s WHERE u.rol='admin';
INSERT INTO usuario_sector SELECT u.id,s.id,1,1 FROM usuarios u JOIN sectores s ON s.slug IN ('operaciones','seguridad','mantenimiento') WHERE u.rol='supervisor';
INSERT INTO usuario_sector SELECT u.id,s.id,1,0 FROM usuarios u JOIN sectores s ON s.slug IN ('operaciones','finanzas','gerencia') WHERE u.rol='ventas';
INSERT INTO usuario_sector SELECT u.id,s.id,1,0 FROM usuarios u JOIN sectores s ON s.slug IN ('operaciones','seguridad') WHERE u.rol='operador';
